    public Reservation testCreate() throws Throwable {
    Reservation entity = null;

    LOGGER.info( "ReservationTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Reservation");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Reservation" );

    try {
        entity = service.createReservation( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getReservationId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Reservation with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

