    /**
     * Tests getting all Reservations.
     *
     * @return    Collection
     */
    public List<Reservation> testGetAll() throws Throwable {
    LOGGER.info( "ReservationTest:testGetAll() - Retrieving Collection of Reservations:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Reservation : " );
    List<Reservation> collection  = null;

    try {
        // call the static get method on the ReservationService
        collection = service.getAllReservation();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Reservation currEntity  = null;
            Iterator<Reservation> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getReservationId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

